entries[125355] = { ["name"] = "Heilende Sphäre", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt, besteht eine Chance von 50%, dass eine heilende Sphäre entsteht.\n\nGegner, die von Eurer Fähigkeit 'Blackout-Tritt' getötet werden, haben eine Chance von 50%, eine Chisphäre zu erzeugen.\n\nHeilende Sphäre\nBildet eine heilende Sphäre. Wenn Ihr durch sie hindurchlauft, werdet Ihr um 15% Eurer Gesamtgesundheit geheilt. Hält 30 Sek. lang an.\n\nChisphäre\nEine Energieansammlung steigt aus dem Körper eines gefallenen Gegners auf. Wenn Ihr durch Eure Chisphäre hindurchlauft, wird 1 Chi wiederhergestellt. Hält 2 Min. lang an." }
