entries[126455] = { ["name"] = "Aufstand niederschmettern", ["text"] = "15 Meter Reichweite\nSofort\nAlle Echos von Pandarenmönchen, die in Reichweite des Geists von Lao-Fe sind, werden sofort besiegt.nLao-Fe ist als einer der gewaltsamsten Mogutyrannen dafür bekannt, Möchtegernrebellen gnadenlos niederzuschmettern." }
